    /// <summary>
    /// Resolves a Unicode property escape to code point ranges.
    /// Supports: \p{Lu}, \p{General_Category=Lu}, \p{gc=Lu},
    /// \p{Script=Latin}, \p{sc=Latn}, \p{Script_Extensions=Latin},
    /// \p{scx=Latn}, \p{ASCII}, \p{Alphabetic}, etc.
    /// </summary>
    /// <returns>Array of (Start, End) ranges, or null if property not found.</returns>
    public static (int Start, int End)[]? Resolve(string propertyExpression)
    {
        // Check for key=value syntax: General_Category=Lu, gc=Lu, Script=Latin, etc.
        var eqIndex = propertyExpression.IndexOf('=');
        if (eqIndex >= 0)
        {
            var key = propertyExpression.AsSpan(0, eqIndex).Trim().ToString();
            var value = propertyExpression.AsSpan(eqIndex + 1).Trim().ToString();

            if (key is "General_Category" or "gc")
            {
                // Resolve alias to canonical short name
                if (GeneralCategoryAliases.TryGetValue(value, out var canonical))
                    value = canonical;
                return GeneralCategoryRanges.GetValueOrDefault(value);
            }

            if (key is "Script" or "sc")
            {
                // Resolve script alias
                if (ScriptAliases.TryGetValue(value, out var canonical))
                    value = canonical;
                return ScriptRanges.GetValueOrDefault(value);
            }

            if (key is "Script_Extensions" or "scx")
            {
                // Resolve script alias
                if (ScriptAliases.TryGetValue(value, out var canonical))
                    value = canonical;

                if (value == "Unknown")
                {
                    return GeneralCategoryRanges.GetValueOrDefault("Cn");
                }

                return ScriptExtensionRanges.GetValueOrDefault(value) ?? ScriptRanges.GetValueOrDefault(value);
            }

            return null; // Unknown property key
        }

        // No key=value syntax. Try in order:
        // 1. General_Category (short or long name)
        if (GeneralCategoryAliases.TryGetValue(propertyExpression, out var gcCanonical))
        {
            return GeneralCategoryRanges.GetValueOrDefault(gcCanonical);
        }

        // 2. Binary property
        if (BinaryPropertyRanges.TryGetValue(propertyExpression, out var binaryRanges))
        {
            return binaryRanges;
        }

        // 3. Script (long name)
        if (ScriptRanges.TryGetValue(propertyExpression, out var scriptRanges))
        {
            return scriptRanges;
        }

        return null; // Unknown property
    }
}
